// Given a non‐empty ASCII‐lowercase letter in ['a'..='y'], return its
// successor in the ASCII range followed by a newline.  
// 
// Specification:
//   - requires input.len() > 0
//   - requires input[0] ∈ ['a'..='y']
//   - ensures the result has length 2
//   - ensures result[0] == (input[0] as u8 + 1) as char
//   - ensures result[1] == '\n'
#[requires(input.len() > 0)]
#[requires(input[0] >= 'a' && input[0] <= 'y')]
#[ensures(|res: Vec<char>| 
    res.len() == 2
    && (res[0] as u8) == (input[0] as u8) + 1
    && res[1] == '\n'
)]
fn solve(input: Vec<char>) -> Vec<char> {
    // By precondition, input is non‐empty and input[0] ∈ ['a'..='y'].
    let first = input[0];
    // Re‐check for the verifier
    assert!(first >= 'a' && first <= 'y');

    // Compute its successor in ASCII.
    let next = ((first as u8) + 1) as char;
    // For the verifier: next must be exactly one above first.
    assert!((next as u8) == (first as u8) + 1);

    // Return successor plus newline.
    let result = vec![next, '\n'];
    // Final post‐return assertions for the verifier
    assert!(result.len() == 2);
    assert!(result[0] == next);
    assert!(result[1] == '\n');

    result
}

